import itertools
import json

def solve_puzzle():
    # Input variables
    houses = [1, 2]  # left to right
    names = ["Arnold", "Eric"]
    foods = ["grilled cheese", "pizza"]
    mothers = ["Holly", "Aniya"]

    solutions = []

    # Iterate over all possible assignments (permutations enforce uniqueness across houses)
    for name_assignment in itertools.permutations(names):
        # Clue 2: Arnold is not in the second house (house index 1 in 0-based)
        if name_assignment[1] == "Arnold":
            continue

        for food_assignment in itertools.permutations(foods):
            # Clue 1: The person who loves eating grilled cheese is directly left of the person who is a pizza lover.
            idx_grilled = food_assignment.index("grilled cheese")
            idx_pizza = food_assignment.index("pizza")
            if idx_grilled + 1 != idx_pizza:
                continue

            for mother_assignment in itertools.permutations(mothers):
                # Clue 3: Arnold is the person whose mother's name is Holly.
                arnold_idx = name_assignment.index("Arnold")
                if mother_assignment[arnold_idx] != "Holly":
                    continue

                # If all constraints satisfied, record the solution
                rows = []
                for i, house in enumerate(houses):
                    rows.append([
                        str(house),
                        name_assignment[i],
                        food_assignment[i],
                        mother_assignment[i]
                    ])
                solutions.append(rows)

    # Expect a unique solution; take the first if multiple
    if not solutions:
        raise ValueError("No solution found")
    result_rows = solutions[0]

    result = {
        "solution": {
            "header": ["House", "Name", "Food", "Mother"],
            "rows": result_rows
        }
    }
    return result

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False))
